INSERT INTO questions (id,questionnaire_id,question_key,prompt_th,type,required,options_json,scoring_json,research_construct,sort_order) VALUES ('cq2-pretest-subgame-node-zone-quantum-nzq_a01','cq2-pretest-subgame-node-zone-quantum','nzq_a01','หากเตรียม qubit ให้อยู่ในสถานะซ้อนทับของ |0⟩ และ |1⟩ แล้ววัดหนึ่งครั้งในฐาน |0⟩/|1⟩ จะได้ผลแบบใด','single','1','[{"value":"a","label":"ก. ได้หนึ่งผลลัพธ์ โดยความน่าจะเป็นขึ้นกับสถานะที่เตรียม"},{"value":"b","label":"ข. ได้ค่าทั้ง 0 และ 1 ปรากฏพร้อมกันเป็นผลวัดเดียว"},{"value":"c","label":"ค. ค่าที่วัดได้จะเป็น 0 เสมอเพราะเริ่มจาก qubit"},{"value":"unsure","label":"ง. ยังไม่แน่ใจ"}]',NULL,'cq2_nzq-a01','30');
INSERT INTO questions (id,questionnaire_id,question_key,prompt_th,type,required,options_json,scoring_json,research_construct,sort_order) VALUES ('cq2-pretest-subgame-node-zone-quantum-nzq_a02','cq2-pretest-subgame-node-zone-quantum','nzq_a02','สองสถานะควอนตัมมีขนาดแอมพลิจูดเท่ากัน แต่มีเฟสสัมพัทธ์ต่างกัน ก่อนผ่านวงจรแทรกสอด ผลที่วัดภายหลังอาจเป็นอย่างไร','single','1','[{"value":"a","label":"ก. ต้องเหมือนกันเสมอ เพราะขนาดแอมพลิจูดเท่ากัน"},{"value":"b","label":"ข. แตกต่างได้เพราะเฟสสัมพัทธ์มีผลต่อการแทรกสอด"},{"value":"c","label":"ค. แตกต่างได้เฉพาะเมื่ออุณหภูมิเปลี่ยนเท่านั้น"},{"value":"unsure","label":"ง. ยังไม่แน่ใจ"}]',NULL,'cq2_nzq-a02','40');
