INSERT INTO questions (id,questionnaire_id,question_key,prompt_th,type,required,options_json,scoring_json,research_construct,sort_order) VALUES ('cq2-pretest-subgame-node-zone-quantum-nzq_a04','cq2-pretest-subgame-node-zone-quantum','nzq_a04','เครื่องตรวจวัดสองตัวรายงานระยะต่างกันอย่างสม่ำเสมอ ควรตรวจอะไรเพื่อแยกความผิดพลาดของเครื่องมือ','single','1','[{"value":"a","label":"ก. การสอบเทียบ ช่วงเวลา และข้อมูลจากแหล่งอ้างอิงอิสระ"},{"value":"b","label":"ข. เลือกค่าที่ตรงกับความคาดหวังของผู้วิจัย"},{"value":"c","label":"ค. ใช้ค่าเฉลี่ยทันทีโดยไม่ตรวจสาเหตุ"},{"value":"unsure","label":"ง. ยังไม่แน่ใจ"}]',NULL,'cq2_nzq-a04','60');
