INSERT INTO questions (id,questionnaire_id,question_key,prompt_th,type,required,options_json,scoring_json,research_construct,sort_order) VALUES ('cq2-postgame-subgame-node-zone-quantum-nzq_b01','cq2-postgame-subgame-node-zone-quantum','nzq_b01','นักวิจัยเตรียม qubit สถานะเดียวกันหลายรอบแล้ววัดในฐานเดียวกัน เหตุใดผลวัดจึงอาจแตกต่างกันระหว่างรอบ','single','1','[{"value":"a","label":"ก. เป็นเพราะอุปกรณ์ต้องเสียทุกครั้งที่ผลต่างกัน"},{"value":"b","label":"ข. ผลการวัดเชิงควอนตัมอาจเป็นไปตามการกระจายความน่าจะเป็นของสถานะ"},{"value":"c","label":"ค. เพราะระบบบันทึกผล 0 และ 1 พร้อมกันในแต่ละรอบ"},{"value":"unsure","label":"ง. ยังไม่แน่ใจ"}]',NULL,'cq2_nzq-b01','10');
INSERT INTO questions (id,questionnaire_id,question_key,prompt_th,type,required,options_json,scoring_json,research_construct,sort_order) VALUES ('cq2-postgame-subgame-node-zone-quantum-nzq_b02','cq2-postgame-subgame-node-zone-quantum','nzq_b02','ในวงจรที่แปลงข้อมูลเฟสสัมพัทธ์เป็นความน่าจะเป็นของผลวัด ข้อใดอธิบายสิ่งที่จะเกิดได้ดีที่สุด','single','1','[{"value":"a","label":"ก. เฟสสัมพัทธ์ไม่มีความเกี่ยวข้องกับผลวัดเลย"},{"value":"b","label":"ข. ผลวัดถูกกำหนดด้วยชื่อของ qubit เท่านั้น"},{"value":"c","label":"ค. ความแตกต่างของเฟสอาจเปลี่ยนสัดส่วนผลวัดหลังการแทรกสอด"},{"value":"unsure","label":"ง. ยังไม่แน่ใจ"}]',NULL,'cq2_nzq-b02','20');
INSERT INTO questions (id,questionnaire_id,question_key,prompt_th,type,required,options_json,scoring_json,research_construct,sort_order) VALUES ('cq2-postgame-subgame-node-zone-quantum-nzq_b03','cq2-postgame-subgame-node-zone-quantum','nzq_b03','หากการสูญเสีย coherence ทำให้สัญญาณของเซนเซอร์ควอนตัมอ่อนลง สิ่งใดเหมาะสมก่อนนำค่าไปเปรียบเทียบกับแบบจำลอง','single','1','[{"value":"a","label":"ก. ประเมินผลของสัญญาณที่เสื่อมต่อความคลาดเคลื่อนของตัวประมาณค่า"},{"value":"b","label":"ข. ปรับแบบจำลองจนตรงกับค่าดิบโดยไม่ตรวจเซนเซอร์"},{"value":"c","label":"ค. ถือว่าเป็นหลักฐานว่ามีการเคลื่อนที่ผิดปกติแน่นอน"},{"value":"unsure","label":"ง. ยังไม่แน่ใจ"}]',NULL,'cq2_nzq-b03','30');
INSERT INTO questions (id,questionnaire_id,question_key,prompt_th,type,required,options_json,scoring_json,research_construct,sort_order) VALUES ('cq2-postgame-subgame-node-zone-quantum-nzq_b04','cq2-postgame-subgame-node-zone-quantum','nzq_b04','เซนเซอร์สองระบบวัดเหตุการณ์เดียวกัน แต่ timestamp ของระบบหนึ่งช้ากว่าอีกระบบ วิธีใดน่าเชื่อถือที่สุด','single','1','[{"value":"a","label":"ก. รายงานว่ามีการเคลื่อนที่สองครั้งโดยไม่ตรวจเวลา"},{"value":"b","label":"ข. จัดแนวเวลาและตรวจ calibration ก่อนเปรียบเทียบการอ่านค่า"},{"value":"c","label":"ค. ตัดข้อมูลระบบที่รายงานช้าทิ้งทั้งหมด"},{"value":"unsure","label":"ง. ยังไม่แน่ใจ"}]',NULL,'cq2_nzq-b04','40');
