INSERT INTO questions (id,questionnaire_id,question_key,prompt_th,type,required,options_json,scoring_json,research_construct,sort_order) VALUES ('cq2-pretest-subgame-ka-wa-ve-d10','cq2-pretest-subgame-ka-wa-ve','d10','ก่อนเริ่มคดีนี้ คุณเคยศึกษาหัวข้อวิชาการที่เกี่ยวข้องกับคดีนี้มากน้อยเพียงใด','single','1','[{"value":"option_1","label":"ไม่เคยศึกษามาก่อน"},{"value":"option_2","label":"เคยอ่านหรือฟังผ่าน ๆ"},{"value":"option_3","label":"เคยเรียนพื้นฐานในห้องเรียน"},{"value":"option_4","label":"เคยศึกษาเพิ่มเติมด้วยตัวเอง/ทำกิจกรรม"},{"value":"option_5","label":"เคยทำโครงงานหรือศึกษาค่อนข้างลึก"}]',NULL,'cq2_d10','20');
INSERT INTO questions (id,questionnaire_id,question_key,prompt_th,type,required,options_json,scoring_json,research_construct,sort_order) VALUES ('cq2-pretest-subgame-ka-wa-ve-wv_a01','cq2-pretest-subgame-ka-wa-ve','wv_a01','ผลตรวจชีวเคมีของผู้ป่วยคนหนึ่งผิดปกติ แต่อาการเกิดหลังรับประทานอาหารหลายชั่วโมง ข้อใดช่วยประเมินสาเหตุได้เหมาะสม','single','1','[{"value":"a","label":"ก. เทียบเวลาเก็บตัวอย่าง อาการ ประวัติ และผลตรวจที่เกี่ยวข้อง"},{"value":"b","label":"ข. ใช้ผลตรวจค่าที่ผิดปกติเพียงค่าเดียวตัดสินสาเหตุ"},{"value":"c","label":"ค. สรุปจากข่าวลือว่าใครอยู่ใกล้ผู้ป่วย"},{"value":"unsure","label":"ง. ยังไม่แน่ใจ"}]',NULL,'cq2_wv-a01','30');
INSERT INTO questions (id,questionnaire_id,question_key,prompt_th,type,required,options_json,scoring_json,research_construct,sort_order) VALUES ('cq2-pretest-subgame-ka-wa-ve-wv_a02','cq2-pretest-subgame-ka-wa-ve','wv_a02','ห้องแล็บตรวจสารสองชนิดที่เกี่ยวข้องกับการผลิตฮอร์โมนชนิดหนึ่งภายในร่างกายได้ เหตุใดจึงควรใช้ข้อมูลทั้งคู่','single','1','[{"value":"a","label":"ก. ค่าทั้งคู่บอกผู้กระทำผิดโดยตรง"},{"value":"b","label":"ข. รูปแบบของสารที่สัมพันธ์กันอาจช่วยแยกกลไกการสร้าง/รับสาร แต่ต้องตีความร่วมกับบริบท"},{"value":"c","label":"ค. การมีสองค่าทำให้ไม่ต้องสนใจวิธีเก็บตัวอย่าง"},{"value":"unsure","label":"ง. ยังไม่แน่ใจ"}]',NULL,'cq2_wv-a02','40');
INSERT INTO questions (id,questionnaire_id,question_key,prompt_th,type,required,options_json,scoring_json,research_construct,sort_order) VALUES ('cq2-pretest-subgame-ka-wa-ve-wv_a03','cq2-pretest-subgame-ka-wa-ve','wv_a03','รายงานพิษวิทยาพบสารออกฤทธิ์ในตัวอย่างชีวภาพหนึ่งชนิด สิ่งใดสรุปได้อย่างเหมาะสม','single','1','[{"value":"a","label":"ก. พิสูจน์ได้ว่าเกิดการวางยาโดยเจตนา"},{"value":"b","label":"ข. ระบุได้ทันทีว่าใครเป็นผู้ให้สาร"},{"value":"c","label":"ค. สนับสนุนการได้รับสัมผัสสารตามขอบเขตวิธีตรวจ แต่ยังไม่ระบุเจตนาหรือผู้ให้"},{"value":"unsure","label":"ง. ยังไม่แน่ใจ"}]',NULL,'cq2_wv-a03','50');
INSERT INTO questions (id,questionnaire_id,question_key,prompt_th,type,required,options_json,scoring_json,research_construct,sort_order) VALUES ('cq2-pretest-subgame-ka-wa-ve-wv_a04','cq2-pretest-subgame-ka-wa-ve','wv_a04','นักสืบเชื่อสมมติฐานแรกของตนและค้นหาเฉพาะสิ่งที่สนับสนุนพฤติกรรมนั้น สอดคล้องกับแนวคิดใด','single','1','[{"value":"a","label":"ก. การควบคุมตัวแปรรบกวน"},{"value":"b","label":"ข. อคติยืนยันความเชื่อเดิม (confirmation bias)"},{"value":"c","label":"ค. การสุ่มตัวอย่างแบบเป็นกลาง"},{"value":"unsure","label":"ง. ยังไม่แน่ใจ"}]',NULL,'cq2_wv-a04','60');
INSERT INTO questions (id,questionnaire_id,question_key,prompt_th,type,required,options_json,scoring_json,research_construct,sort_order) VALUES ('cq2-pretest-subgame-ka-wa-ve-wv_a05','cq2-pretest-subgame-ka-wa-ve','wv_a05','พบข้อความแสดงความขัดแย้งระหว่างเพื่อนร่วมงานก่อนเกิดเหตุ การใช้ข้อมูลนี้ควรทำอย่างไร','single','1','[{"value":"a","label":"ก. ใช้เป็นบริบทของความสัมพันธ์ แต่ต้องหาหลักฐานการกระทำแยกต่างหาก"},{"value":"b","label":"ข. ถือเป็นหลักฐานที่ระบุตัวผู้กระทำได้โดยไม่ต้องตรวจเพิ่ม"},{"value":"c","label":"ค. มองว่าไม่มีประโยชน์ต่อการตั้งสมมติฐานใด ๆ"},{"value":"unsure","label":"ง. ยังไม่แน่ใจ"}]',NULL,'cq2_wv-a05','70');
INSERT INTO questions (id,questionnaire_id,question_key,prompt_th,type,required,options_json,scoring_json,research_construct,sort_order) VALUES ('cq2-pretest-subgame-ka-wa-ve-wv_a06','cq2-pretest-subgame-ka-wa-ve','wv_a06','พยานทำงานภายใต้ผู้จัดการที่มีอำนาจประเมินงานของตน ควรประเมินคำบอกเล่าอย่างไร','single','1','[{"value":"a","label":"ก. ถือว่าเชื่อถือได้แน่นอนเพราะเป็นพนักงานในองค์กร"},{"value":"b","label":"ข. ปฏิเสธว่าเท็จทั้งหมดโดยไม่มีการตรวจสอบ"},{"value":"c","label":"ค. พิจารณาแรงกดดันและตรวจไขว้กับหลักฐานอิสระ"},{"value":"unsure","label":"ง. ยังไม่แน่ใจ"}]',NULL,'cq2_wv-a06','80');
