INSERT INTO questions (id,questionnaire_id,question_key,prompt_th,type,required,options_json,scoring_json,research_construct,sort_order) VALUES ('cq2-postgame-subgame-ka-wa-ve-wv_b02','cq2-postgame-subgame-ka-wa-ve','wv_b02','กรณีหนึ่งมีฮอร์โมนเพิ่มสูง แต่ยังไม่ทราบแหล่งที่มา การตรวจสารร่วมที่ถูกปล่อยจากกระบวนการสร้างในร่างกายช่วยอะไรได้','single','1','[{"value":"a","label":"ก. ช่วยประเมินความเป็นไปได้ของกลไกการสร้างภายในร่างกายเมื่อดูคู่กับข้อมูลอื่น"},{"value":"b","label":"ข. พิสูจน์เจตนาของบุคคลที่เกี่ยวข้อง"},{"value":"c","label":"ค. ทดแทนการตรวจประวัติและช่วงเวลาได้เสมอ"},{"value":"unsure","label":"ง. ยังไม่แน่ใจ"}]',NULL,'cq2_wv-b02','20');
INSERT INTO questions (id,questionnaire_id,question_key,prompt_th,type,required,options_json,scoring_json,research_construct,sort_order) VALUES ('cq2-postgame-subgame-ka-wa-ve-wv_b03','cq2-postgame-subgame-ka-wa-ve','wv_b03','เมื่อตรวจพบสารที่อาจก่อผลต่อสรีรวิทยาในร่างกาย จำเป็นต้องตรวจอะไรเพิ่มเติมก่อนอ้างว่าเป็นสาเหตุของการเสียชีวิต','single','1','[{"value":"a","label":"ก. พิจารณาความเข้มข้น เวลา อาการ กลไก และคำอธิบายทางเลือก"},{"value":"b","label":"ข. ใช้เพียงการตรวจพบสารก็เพียงพอจะยืนยันสาเหตุทั้งหมด"},{"value":"c","label":"ค. เลือกคำอธิบายตามบุคคลที่มีแรงจูงใจสูงสุด"},{"value":"unsure","label":"ง. ยังไม่แน่ใจ"}]',NULL,'cq2_wv-b03','30');
