INSERT INTO questions (id,questionnaire_id,question_key,prompt_th,type,required,options_json,scoring_json,research_construct,sort_order) VALUES ('cq2-pretest-subgame-ka-fintech-mf_a03','cq2-pretest-subgame-ka-fintech','mf_a03','พบยอดใน ledger ไม่ตรงกับรายการธุรกรรมที่ควรประกอบกัน วิธีตรวจใดรักษาความน่าเชื่อถือของหลักฐานได้ดีที่สุด','single','1','[{"value":"a","label":"ก. แก้ยอดสรุปก่อนแล้วลบรายการที่ต่างออกไป"},{"value":"b","label":"ข. ใช้ภาพหน้าจอเพียงภาพเดียวแทน raw ledger"},{"value":"c","label":"ค. ตรวจ log การแก้ไข รายการต้นทาง และเส้นทางมูลค่าโดยไม่ทำลายต้นฉบับ"},{"value":"unsure","label":"ง. ยังไม่แน่ใจ"}]',NULL,'cq2_mf-a03','50');
INSERT INTO questions (id,questionnaire_id,question_key,prompt_th,type,required,options_json,scoring_json,research_construct,sort_order) VALUES ('cq2-pretest-subgame-ka-fintech-mf_a04','cq2-pretest-subgame-ka-fintech','mf_a04','เมื่อการตรวจลายเซ็นดิจิทัลผ่าน โดยใช้กุญแจสาธารณะที่ตรวจสอบความสัมพันธ์กับเจ้าของกุญแจแล้ว ข้อใดได้รับการสนับสนุน','single','1','[{"value":"a","label":"ก. เจ้าของชื่อบัญชีต้องกดลงนามด้วยตนเองทุกครั้ง"},{"value":"b","label":"ข. ลายเซ็นสัมพันธ์กับกุญแจและข้อความไม่ถูกแก้ในส่วนที่ลงนาม แต่ต้องพิจารณาการคุ้มครองกุญแจด้วย"},{"value":"c","label":"ค. ข้อความที่ลงนามเป็นข้อเท็จจริงทั้งหมด"},{"value":"unsure","label":"ง. ยังไม่แน่ใจ"}]',NULL,'cq2_mf-a04','60');
INSERT INTO questions (id,questionnaire_id,question_key,prompt_th,type,required,options_json,scoring_json,research_construct,sort_order) VALUES ('cq2-pretest-subgame-ka-fintech-mf_a05','cq2-pretest-subgame-ka-fintech','mf_a05','log บัตรผ่านไม่พบเหตุการณ์เปิดประตูในช่วงหนึ่ง ข้อใดเป็นข้อจำกัดของข้อสรุปจาก log นี้','single','1','[{"value":"a","label":"ก. อาจมีช่องทางอื่นหรือข้อมูลขาดหาย ต้องตรวจความครบถ้วนและการเทียบเวลา"},{"value":"b","label":"ข. พิสูจน์ว่าไม่มีผู้ใดเข้าออกพื้นที่แน่นอน"},{"value":"c","label":"ค. พิสูจน์ว่าระบบกล้องทุกตัวทำงานถูกต้อง"},{"value":"unsure","label":"ง. ยังไม่แน่ใจ"}]',NULL,'cq2_mf-a05','70');
INSERT INTO questions (id,questionnaire_id,question_key,prompt_th,type,required,options_json,scoring_json,research_construct,sort_order) VALUES ('cq2-pretest-subgame-ka-fintech-mf_a06','cq2-pretest-subgame-ka-fintech','mf_a06','ธุรกรรมทำผ่านบัญชีพนักงานหนึ่งราย จะพิสูจน์ว่าเจ้าตัวเป็นผู้ทำได้หรือไม่','single','1','[{"value":"a","label":"ก. ได้แน่นอนเพราะชื่อบัญชีตรง"},{"value":"b","label":"ข. ได้หากมีเพียงรหัสผ่านที่ถูกต้อง โดยไม่ต้องตรวจอุปกรณ์"},{"value":"c","label":"ค. ยังต้องตรวจการเข้าถึง การใช้ credential และหลักฐานประกอบอื่น"},{"value":"unsure","label":"ง. ยังไม่แน่ใจ"}]',NULL,'cq2_mf-a06','80');
